import requests

def search_contact(pipedrive_api_key, company_domain, phone, email, phone_2_pipedrive_field_key, email_2_pipedrive_field_key):
    base_url = f"https://{company_domain}.pipedrive.com/api/v2"
    headers = {
        "x-api-token": pipedrive_api_key
    }
    search_performed = False  # Flag, um zu überprüfen, ob eine Suche durchgeführt wurde

    # 1. Suche nach Telefon 1, falls vorhanden
    if phone:
        search_performed = True
        url = f"{base_url}/persons/search"
        params = {
            'term': phone,
            'fields': 'phone',
            'exact_match': True
        }
        response = requests.get(url, headers=headers, params=params)

        if response.status_code == 200:
            data = response.json()
            if data.get("data") and data["data"].get("items") and data["data"]["items"]:
                person_id = data["data"]["items"][0]["item"]["id"]
                return {"success": True, "person_id": person_id}

    # 2. Suche nach E-Mail 1, falls vorhanden
    if email:
        search_performed = True
        url = f"{base_url}/persons/search"
        params = {
            'term': email,
            'fields': 'email',
            'exact_match': True
        }
        response = requests.get(url, headers=headers, params=params)

        if response.status_code == 200:
            data = response.json()
            if data.get("data") and data["data"].get("items") and data["data"]["items"]:
                person_id = data["data"]["items"][0]["item"]["id"]
                return {"success": True, "person_id": person_id}

    # 3. Suche nach Telefon 2 - NUR wenn phone UND field_key vorhanden
    if phone and phone_2_pipedrive_field_key:
        url = f"{base_url}/itemSearch/field"
        params = {
            'term': phone,
            'entity_type': 'person',
            'field': phone_2_pipedrive_field_key,
            'match': 'exact'
        }
        response = requests.get(url, headers=headers, params=params)

        if response.status_code == 200:
            data = response.json()
            if data.get("data") and data["data"]:
                person_id = data["data"][0]["id"]
                return {"success": True, "person_id": person_id}

    # 4. Suche nach E-Mail 2 - NUR wenn email UND field_key vorhanden
    if email and email_2_pipedrive_field_key:
        url = f"{base_url}/itemSearch/field"
        params = {
            'term': email,
            'entity_type': 'person',
            'field': email_2_pipedrive_field_key,
            'match': 'exact'
        }
        response = requests.get(url, headers=headers, params=params)

        if response.status_code == 200:
            data = response.json()
            if data.get("data") and data["data"]:
                person_id = data["data"][0]["id"]
                return {"success": True, "person_id": person_id}

    # Überprüfe, ob überhaupt eine Suche durchgeführt wurde
    if not search_performed:
        return {"success": False, "person_id": None, "error_message": "Keine Suchkriterien vorhanden."}

    # Wenn keine Person gefunden wurde
    return {"success": False, "person_id": None, "error_message": "Keine übereinstimmende Person gefunden."}

